using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
namespace Dafeiyu.Tests {
 public static class ConversationVisualTests {
  static int checks;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
  static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in All<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
  static void Pump(int milliseconds){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(milliseconds)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static byte[] Pixels(FrameworkElement element){var bitmap=new RenderTargetBitmap((int)Math.Ceiling(element.ActualWidth),(int)Math.Ceiling(element.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(element);var bytes=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];bitmap.CopyPixels(bytes,bitmap.PixelWidth*4,0);return bytes;}
  static bool Moves(byte[] first,byte[] second){int pixels=0,changed=0;for(int i=0;i<first.Length;i+=4){if(first[i+3]<30&&second[i+3]<30)continue;pixels++;if(Math.Abs(first[i]-second[i])+Math.Abs(first[i+1]-second[i+1])+Math.Abs(first[i+2]-second[i+2])>30)changed++;}return pixels>0&&changed>pixels*.15;}
  [STAThread]public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};PetWindow pet=null;Window sample=null;string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"visual-"+Guid.NewGuid().ToString("N"));try{
   var cfg=new PetSettings{AutoUpdate=false,GreetingEnabled=false,ShowPredictedMessages=false,ReadReplies=false,OnboardingState="completed"};foreach(var key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"settings.json")),null);
   foreach(string tool in new[]{"","edit_file","run_command","plain-chat"}){
    var log=new ConversationLog();ChatMessage user;var reply=log.BeginTurn("fixture","text",out user);reply=log.StartProcessing(reply.Id,tool!="plain-chat");if(tool!=""&&tool!="plain-chat"){reply.SetTools(new[]{new AgentToolEvent{Id="test",Name=tool,Summary="fixture.txt",Status="running"}});}
    var history=new StackPanel();sample=new Window{Content=history,Width=500,Height=260};var view=new ChatMessageView(reply,history,pet,sample);history.Children.Add(view);sample.Show();Pump(180);var label=All<TextBlock>(view).Single(t=>t.Name=="ProcessStatus");Check(label.IsVisible&&label.ActualWidth>15,"activity text is rendered: "+tool);var first=Pixels(label);Pump(430);Check(SystemParameters.ClientAreaAnimation?Moves(first,Pixels(label)):first.SequenceEqual(Pixels(label)),"visible activity follows system motion preference: "+tool);
    var brush=typeof(ChatMessageView).GetField("shimmerBrush",hidden).GetValue(view);Check(SystemParameters.ClientAreaAnimation?brush!=null:brush==null&&label.Foreground==AgentUi.Muted,"activity brush follows system motion preference: "+tool);view.Update(reply);Check(Object.ReferenceEquals(brush,typeof(ChatMessageView).GetField("shimmerBrush",hidden).GetValue(view)),"streaming snapshot preserves the running animation: "+tool);
    history.Children.Remove(view);Pump(100);Check(typeof(ChatMessageView).GetField("shimmerBrush",hidden).GetValue(view)==null,"unloaded activity releases animation: "+tool);history.Children.Add(view);Pump(160);first=Pixels(label);Pump(430);Check(SystemParameters.ClientAreaAnimation?Moves(first,Pixels(label)):first.SequenceEqual(Pixels(label)),"reloaded pending activity follows system motion preference: "+tool);
    reply=log.Update(reply.Id,"done","complete");view.Update(reply);Check(typeof(ChatMessageView).GetField("shimmerBrush",hidden).GetValue(view)==null,"completed activity releases animation: "+tool);sample.Close();sample=null;
   }
   pet.ShowChat();var chat=app.Windows.OfType<ChatWindow>().Single();foreach(double width in new[]{1000d,1450d}){chat.Width=width;Pump(200);var rail=All<Border>(chat).Single(b=>b.Name=="AppIconRail");var avatar=All<Button>(chat).Single(b=>b.Name=="ShellAvatar");var settings=All<Button>(chat).Single(b=>b.Name=="ShellSettings");Point icon=settings.TranslatePoint(new Point(settings.ActualWidth/2,settings.ActualHeight/2),rail),face=avatar.TranslatePoint(new Point(avatar.ActualWidth/2,avatar.ActualHeight/2),rail);Check(settings.IsVisible&&avatar.IsVisible&&Math.Abs(icon.X-face.X)<1,"rail settings and avatar share the same horizontal centre at width "+width);Check(icon.X-settings.ActualWidth/2>=5&&rail.ActualWidth-(icon.X+settings.ActualWidth/2)>=5,"rail icons keep their full inset and remain unclipped at width "+width);var oldSettings=All<Button>(chat).Single(b=>b.Name=="WorkspaceProjectSettings");Check(!oldSettings.IsVisible,"obsolete sidebar settings does not duplicate the rail entry");}
   chat.Close();Console.WriteLine("Conversation visual tests: "+checks+" passed");return 0;
  }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{if(sample!=null)sample.Close();foreach(var chat in app.Windows.OfType<ChatWindow>().ToArray())chat.Close();if(pet!=null)pet.Close();app.Shutdown();}}
 }
}
